import json,sys,urllib.request
def get(u):
    return json.load(urllib.request.urlopen(u))
d=get("http://127.0.0.1:9090/api/v1/query?query=probe_success")["data"]["result"]
for r in d: print("probe_success", r["metric"].get("job"), r["metric"].get("instance"), r["value"][1])
d=get("http://127.0.0.1:9090/api/v1/alerts")["data"]["alerts"]
for a in d: print("alert", a["labels"].get("alertname"), a["state"], a["labels"].get("instance"))
d=get("http://127.0.0.1:9093/api/v2/alerts")
for a in d: print("am", a["labels"].get("alertname"), a["status"]["state"], a["receivers"][0]["name"] if a.get("receivers") else "")
f=get("http://127.0.0.1:9090/api/v1/status/flags")["data"]
for k in sorted(f):
    print("flag", k, f[k])
EOF
cat /tmp/q.py | $G 'cat > /tmp/q.py && python3 /tmp/q.py' 2>&1 | head -120

